import { SqliteEventStore } from "@moe/store";
import { recordPublishReceipt, readPublishReceipt } from "./src/repository/publish-ledger.js";
import { publishAggregateId, publishReceiptId } from "./src/repository/publish-receipt-contracts.js";
const store = SqliteEventStore.openEphemeralForProjectTest("p1");
const enc = new TextEncoder();
const agg = publishAggregateId("g1");
// Any peer write on the goal's publish aggregate (an observation, an intent, another receipt).
store.commitExpectedVersionDecision({ commandKind: "internal.repository.publication_observation", committedResultBytes: enc.encode("{}"),
  correlationId: "peer", decidedAt: "2026-09-19T00:00:00.000Z", events: [{ eventId: "peer-1", eventType: "Peer", payload: enc.encode("{}") }],
  expectedVersion: store.getAggregateVersion(agg), key: { commandId: "peer-1", principalId: "daemon:node-publisher", projectId: "p1" },
  requestBytes: enc.encode("{}"), targetAggregateId: agg });
const base = { branch: "b", decidedAt: "2026-09-19T00:00:01.000Z", decisionId: "d1", goalId: "g1", projectId: "p1",
  remoteUrl: "https://github.com/o/r.git", sha: "a".repeat(40), url: null };
// The receipt writer read the version BEFORE the peer write committed: emulate with a version one behind.
const stale = new Proxy(store, { get(t, k) {
  if (k === "getAggregateVersion") return (id) => t.getAggregateVersion(id) - 1;
  const v = Reflect.get(t, k, t); return typeof v === "function" ? v.bind(t) : v; } });
console.log("first write (stale version):", JSON.stringify(recordPublishReceipt(stale, { ...base, refusal: { code: "PUBLISH_RESOLVED_ABANDON", detail: "x" } })));
console.log("retry, fresh version       :", JSON.stringify(recordPublishReceipt(store, { ...base, refusal: { code: "PUBLISH_RESOLVED_ABANDON", detail: "x" } })));
console.log("publisher PUSHED later     :", JSON.stringify(recordPublishReceipt(store, { ...base, refusal: null })));
console.log("read of the receipt key    :", JSON.stringify(readPublishReceipt(store, "p1", publishReceiptId("p1", "g1", "d1"))));
store.close();
```

